class LabTestItem {
  final String id;
  final String image;
  final String categoryId;
  final String categoryEn;
  final String categoryBn;
  final Color categoryColor;
  final IconData categoryIcon;
  final String name;
  final String shortDescriptionEn;
  final String shortDescriptionBn;
  final String whatIsItEn;
  final String whatIsItBn;
  final String whyItIsImportantEn;
  final String whyItIsImportantBn;
  final String howItIsDoneEn;
  final String howItIsDoneBn;
  final String standardMethodEn;
  final String standardMethodBn;
  final String commonFailureCausesEn;
  final String commonFailureCausesBn;
  final String? formulaEn;
  final String? formulaBn;
  final String resultUnitEn;
  final String resultUnitBn;
  final String resultEvaluationEn;
  final String resultEvaluationBn;

  const LabTestItem({
    required this.id,
    required this.image,
    required this.categoryId,
    required this.categoryEn,
    required this.categoryBn,
    required this.categoryColor,
    required this.categoryIcon,
    required this.name,
    required this.shortDescriptionEn,
    required this.shortDescriptionBn,
    required this.whatIsItEn,
    required this.whatIsItBn,
    required this.whyItIsImportantEn,
    required this.whyItIsImportantBn,
    required this.howItIsDoneEn,
    required this.howItIsDoneBn,
    required this.standardMethodEn,
    required this.standardMethodBn,
    required this.commonFailureCausesEn,
    required this.commonFailureCausesBn,
    required this.resultUnitEn,
    required this.resultUnitBn,
    required this.resultEvaluationEn,
    required this.resultEvaluationBn,
    this.formulaEn,
    this.formulaBn,
  });
}

