    resultEvaluationEn: 'A higher recovery angle generally indicates better wrinkle resistance; the desired value depends on the finish type and buyer specification.',
    resultEvaluationBn: 'উচ্চতর কোণ (রিকভারি অ্যাঙ্গেল) সাধারণত ভালো কুঁচকানো-প্রতিরোধ ক্ষমতা নির্দেশ করে; কাঙ্ক্ষিত মান ফিনিশ টাইপ ও বায়ার স্পেসিফিকেশনের ওপর নির্ভর করে।',
