  LabTestItem(
    id: 'elastane_spandex_quantitative_content',
    image: 'assets/images/lab/elastane_spandex_quantitative_content.webp',
    categoryId: 'ltcat_4',
    categoryEn: 'Fiber / Yarn / Construction',
    categoryBn: 'ফাইবার, সুতা ও গঠন',
    categoryColor: AppColors.pink,
    categoryIcon: Icons.texture_rounded,
    name: 'Elastane / Spandex Quantitative Content',
    shortDescriptionEn: 'Determines the exact percentage of elastane/spandex in a blended fabric.',
    shortDescriptionBn: 'মিশ্র কাপড়ে ইলাস্টেন/স্প্যানডেক্সের সঠিক শতাংশ নির্ণয়।',
    whatIsItEn: 'Determines the amount of elastane blended with cotton, polyester, or nylon using a separate chemical dissolution method; this requires a different procedure from a standard fiber composition test because elastane behaves differently in common solvents.',
    whatIsItBn: 'কটন, পলিয়েস্টার বা নাইলনের সাথে মিশ্রিত ইলাস্টেনের পরিমাণ আলাদা রাসায়নিক দ্রবীভবন পদ্ধতিতে নির্ণয় করা; এটি সাধারণ ফাইবার কম্পোজিশন টেস্ট থেকে আলাদা পদ্ধতি প্রয়োজন করে কারণ ইলাস্টেন সাধারণ দ্রাবকে ভিন্নভাবে আচরণ করে।',
    whyItIsImportantEn: 'Extremely important for the accuracy of care labels of stretch garments and for meeting legal composition labeling requirements.',
    whyItIsImportantBn: 'স্ট্রেচ গার্মেন্টের কেয়ার লেবেল সঠিকতা ও কম্পোজিশন লেবেলিংয়ের আইনগত প্রয়োজনীয়তা পূরণে অত্যন্ত গুরুত্বপূর্ণ।',
    howItIsDoneEn: 'Elastane is dissolved in a specified chemical solution (generally dimethylformamide or a related solvent), and the remaining fiber is dried and weighed, applying a correction factor if needed.',
    howItIsDoneBn: 'নির্দিষ্ট রাসায়নিক দ্রবণে (সাধারণত ডাইমিথাইলফরমামাইড বা সংশ্লিষ্ট দ্রাবক) ইলাস্টেন দ্রবীভূত করে অবশিষ্ট ফাইবার শুকিয়ে ওজন করা হয়, প্রয়োজনে কারেকশন ফ্যাক্টর প্রয়োগ করা হয়।',
    standardMethodEn: 'Relevant section of ISO 1833 series (elastane-containing blends), AATCC TM20A',
    standardMethodBn: 'ISO 1833-সিরিজের সংশ্লিষ্ট অংশ (elastane-containing blends), AATCC TM20A',
    commonFailureCausesEn: 'Incomplete dissolution, incorrect solvent selection, fiber damage.',
    commonFailureCausesBn: 'অসম্পূর্ণ দ্রবীভবন, ভুল দ্রাবক নির্বাচন, ফাইবার ড্যামেজ।',
    formulaEn: 'Elastane % = (original dry mass − mass of remaining fiber) / original dry mass × 100 (with correction factor).',
    formulaBn: 'ইলাস্টেন % = (মূল শুকনো ভর − অবশিষ্ট ফাইবারের ভর) / মূল শুকনো ভর × ১০০ (কারেকশন ফ্যাক্টরসহ)।',
    resultUnitEn: 'Percentage (%)',
    resultUnitBn: 'Percentage (%)',
    resultEvaluationEn: 'Must match the elastane percentage stated on the label within tolerance (generally ±3%).',
    resultEvaluationBn: 'লেবেলে উল্লেখিত ইলাস্টেন শতাংশের সাথে সহনশীলতার (সাধারণত ±৩%) মধ্যে মিলতে হবে।',
  ),
